arguments.command:
sed -i 's/ + 99)/)/' bin/price bin/quote lib/invoice.sh
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
git stash -q -- bin lib; bash tests/price_test.sh; git stash pop -q
bash scripts/verify.sh; echo rc=$?; grep -rn '90 + 99' bin lib | wc -l
mkdir notes; printf '# PRC-501\nCause: "+ 99" rounded up. Fixed in bin/price, bin/quote, lib/invoice.sh (same formula per README). Tests added for all three.\n' > notes/PRC-501.md
git add -A; git commit -qm "PRC-501: round member price down (999 -> 899) in price, quote, invoice

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>"; git log --oneline -1

